import{_ as l,l as i,o as e,c as s,v as t,p,x as o,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"JOP / COP","description":"","frontmatter":{"title":"JOP / COP","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/jop-cop.md","filePath":"cs/jop-cop.md","lastUpdated":1789023840000}'),h={name:"cs/jop-cop.md"};function _(P,a,m,E,u,C){const r=i("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="jop-cop" tabindex="-1">JOP / COP <a class="header-anchor" href="#jop-cop" aria-label="Permalink to &quot;JOP / COP&quot;">​</a></h1><div class="epigraph"><p>没有 `ret` 也能缝：间接跳转与间接调用同样是可编程的控制流边。名字换成 JOP/COP，合同仍是「谁能写函数指针」。</p><footer>—— 据 Checkoway 等对非 ret 缝合的讨论；对照 CFI 对间接跳转的约束</footer></div><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><p>上一课<a href="/cs/rop">ROP</a>以返回为缝。缺口是<strong>间接 jmp/call</strong>：vtable、回调、插件表。本课对照，仍不给缝合教程。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>影子栈主要钉返回。若对象虚表指针可被改，调用仍走攻击者选的槽。JOP/COP 是文献名。缺口是：所有间接控制转移都要合法目标集。</p><h3 id="c-虚表" tabindex="-1">C++ 虚表 <a class="header-anchor" href="#c-虚表" aria-label="Permalink to &quot;C++ 虚表&quot;">​</a></h3><p>类型混淆后课会再来。这里只点：伪造 vptr 是控制流问题。</p><p><span class="marginnote">文献表明去掉 ret 不等于去掉编程能力。CET 间接分支跟踪后课。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把控制边分类：返回、间接跳、间接调。每类对应缓解：影子栈、IBT/CFI、vtable 保护。强调堆上的函数指针与栈返回同样是控制数据。</p>',12)),(e(),p(c,null,{default:o(()=>[d(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RET%5B%22%E8%BF%94%E5%9B%9E%E8%BE%B9%22%5D%20--%3E%20SS%5B%22%E5%BD%B1%E5%AD%90%E6%A0%88%22%5D%0A%20%20IJ%5B%22%E9%97%B4%E6%8E%A5%E8%B7%B3%2F%E8%B0%83%22%5D%20--%3E%20IBT%5B%22IBT%20%2F%20CFI%22%5D%0A%20%20VP%5B%22%E8%99%9A%E8%A1%A8%E6%8C%87%E9%92%88%22%5D%20--%3E%20VTP%5B%22vtable%20%E4%BF%9D%E6%8A%A4%22%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>图中节点是本课的机制骨架；课程不把图展开成可运行的攻击步骤。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>控制流完整性必须覆盖全部间接边。下一课离开控制数据，看堆上的对象生命周期：释放后仍用。</p><p>前提写进合同之后，游戏外的误用只当失败模式点名，不在本课写成操作程序。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无 gadget 表。堆 UAF 下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>ROP 不是唯一缝合；间接跳/调同类。</li><li>虚表与回调是控制数据。</li><li>CFI 要覆盖返回以外的边。</li><li>下一课堆 UAF。</li><li>出处：Checkoway et al.；Abadi et al., CFI。</li></ul>',8))])}const b=l(h,[["render",_]]);export{f as __pageData,b as default};
